/**
 * @param {number[]} nums
 * @return {number}
 */
var longestSubsequence = function(nums) {
    let xor = 0;
    let allZeros = true;

    for (const num of nums) {
        xor = xor ^ num;
        allZeros &&= num === 0;
    }

    if (allZeros) return 0;
    if (xor === 0) return nums.length - 1;
    return nums.length;
};
